    @EventHandler( payloadType=CreateOrganizationEvent.class )
    public void handle( CreateOrganizationEvent event) {
	    LOGGER.info("handling CreateOrganizationEvent - " + event );
	    Organization entity = new Organization();
            entity.setOrganizationId( event.getOrganizationId() );
            entity.setName( event.getName() );
            entity.setDefaultCurrency( event.getDefaultCurrency() );
            entity.setDefaultLocale( event.getDefaultLocale() );
            entity.setWebsite( event.getWebsite() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllOrganization( entity );
    }

